import sys

def has_common_digit(a, b):
    """Check if a and b have at least one common digit"""
    str_a = str(a)
    str_b = str(b)
    for ch in str_a:
        if ch in str_b:
            return True
    return False


def get_divisors(x):
    """Get all divisors of x"""
    divisors = set()
    for i in range(1, int(x**0.5) + 1):
        if x % i == 0:
            divisors.add(i)
            divisors.add(x // i)
    return divisors


def solve(x):
    divisors = get_divisors(x)
    count = 0
    for d in divisors:
        if has_common_digit(x, d):
            count += 1
    return count


def main():
    x = int(sys.stdin.readline())
    print(solve(x))

if __name__ == "__main__":
    main()
"}

