def find_max_product(lanterns):
    """Find the maximum product of any pair from the given list of lanterns."""
    if len(lanterns) < 2:
        return float('-inf')

    # Sort the lanterns
    lanterns.sort()

    # Consider all pairs
    max_product = float('-inf')
    for i in range(len(lanterns)):
        for j in range(i + 1, len(lanterns)):
            product = lanterns[i] * lanterns[j]
            max_product = max(max_product, product)

    return max_product

n, m = map(int, input().split())
a = list(map(int, input().split()))
b = list(map(int, input().split()))

# Try hiding each lantern from Tommy
min_max_product = float('inf')
for i in range(n):
    # Remaining lanterns after hiding a[i]
    remaining_a = a[:i] + a[i+1:]

    # Find maximum product Banban can get
    max_product = float('-inf')
    for x in remaining_a:
        for y in b:
            product = x * y
            if product > max_product:
                max_product = product

    min_max_product = min(min_max_product, max_product)

print(min_max_product)
