import sys

def can_form_triangle(a):
    """Check if we can form a non-degenerate triangle with the given lengths."""
    # Sort the array
    a.sort()

    # Check all triplets (i, j, k) where i < j < k
    for i in range(len(a) - 2):
        for j in range(i + 1, len(a) - 1):
            for k in range(j + 1, len(a)):
                # Check triangle inequality
                if a[i] + a[j] > a[k]:
                    return True

    return False

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    if can_form_triangle(a):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
"}

