import sys

def can_form_triangle(a):
    """Check if we can form a non-degenerate triangle with the given lengths."""
    # Sort the array
    a.sort()

    # Check all triplets (i, j, k) where i < j < k
    for i in range(len(a) - 2):
        for j in range(i + 1, len(a) - 1):
            # Early exit if the smallest two sides can't form a triangle with any larger side
            if a[i] + a[j] > a[-1]:
                return True

            # If the sum of the two smallest sides is <= the largest side, no need to check further
            if a[i] + a[j] <= a[j + 1]:
                break

            # Check if there exists a k such that a[i] + a[j] > a[k]
            # Since the array is sorted, if a[i] + a[j] > a[j+1], then it's also > a[j+2], etc.
            # So we just need to check if a[i] + a[j] > a[j+1]

    return False

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    if can_form_triangle(a):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
"}

