import sys

def solve():
    s = sys.stdin.read().strip()
    if not s:
        return
    n = len(s)

    # Dictionary mapping substring -> list of starting indices
    substr_indices = {}

    # Generate all substrings and store first occurrence index
    for i in range(n):
        for l in range(1, n - i + 1):
            substr = s[i:i+l]
            if substr not in substr_indices:
                substr_indices[substr] = i

    # Find longest substring that appears at least twice
    max_len = 0
    for substr, first_idx in substr_indices.items():
        # Get all indices where this substring occurs
        idxs = [i for i, _ in substr_indices.items() if _ == first_idx]
        if len(idxs) >= 2:
            # Check if any two occurrences are at least one apart (overlap is allowed)
            # We need at least one occurrence at index >= first_idx + 1
            idxs.sort()
            for i, idx in enumerate(idxs):
                if i + 1 < len(idxs) and idxs[i+1] >= idx + 1:
                    max_len = max(max_len, len(substr))
                    break

    print(max_len)

if __name__ == '__main__':
    solve()
