A, B, C = map(int, input().split())

if A == 0:
    if B == 0:
        if C == 0:
            print(-1)  # Infinite roots
        else:
            print(0)  # No roots
    else:
        # Linear equation Bx + C = 0
        root = -C / B
        print(1)
        print(f"{root:.10f}")
else:
    # Quadratic equation
    discriminant = B**2 - 4 * A * C
    if discriminant < 0:
        print(0)
    elif discriminant == 0:
        root = -B / (2 * A)
        print(1)
        print(f"{root:.10f}")
    else:
        # Two distinct roots
        sqrt_d = discriminant**0.5
        root1 = (-B + sqrt_d) / (2 * A)
        root2 = (-B - sqrt_d) / (2 * A)
        if root1 > root2:
            root1, root2 = root2, root1
        print(2)
        print(f"{root1:.10f}")
        print(f"{root2:.10f}")
