for col in range(m):
    current_length = 0
    for row in range(n):
        if classroom[row][col] == '.':
            current_length += 1
        else:
            ways_cols += count_ways(current_length)
            current_length = 0
    ways_cols += count_ways(current_length)

# Total ways
total = ways_rows + ways_cols
