n, h, a, b, k = map(int, input().split())

for _ in range(k):
    ta, fa, tb, fb = map(int, input().split())

    if ta == tb:
        # Same tower, just vertical move
        print(abs(fa - fb))
    else:
        # Different towers
        # Strategy: find optimal meeting point x in [a, b]

        # If both are above b
        if fa >= b and fb >= b:
            print((fa - b) + (tb - ta) + (fb - b))
        # If both are below a
        elif fa <= a and fb <= a:
            print((a - fa) + (tb - ta) + (a - fb))
        # If one is above b and one is below a
        elif fa <= a and fb >= b:
            print((b - max(fa, fb)) + (tb - ta) + (min(fa, fb) - a))
        # If one is inside [a, b] and the other is outside
        else:
            # One is inside, one is outside
            # The optimal meeting point is at the closest endpoint
            # If fa <= a and a <= fb <= b:
            if fa <= a and fb >= a:
                print((a - fa) + (fb - a) + 1)
            # If b <= fa <= a and b <= fb <= a:
            elif fa >= b and fb <= b:
                print((fa - b) + (fb - b) + 1)
            # This case should already be covered
            else:
                print(abs(fa - fb) + 1)
