import sys
from collections import deque

def can_reach_one(n, a, b):
    """Check if we can reach 1 from n using operations /a (if divisible) and -b (if >= b)"""
    visited = set()
    queue = deque([n])

    while queue:
        current = queue.popleft()

        if current == 1:
            return True

        if current not in visited:
            visited.add(current)

            # Try dividing by a
            if current % a == 0:
                next_val = current // a
                if next_val not in visited:
                    queue.append(next_val)

            # Try subtracting b
            if current >= b:
                next_val = current - b
                if next_val not in visited:
                    queue.append(next_val)

    return False

def main():
    input = sys.stdin.read().strip().split()
    if not input:
        return

    t = int(input[0])
    idx = 1

    for _ in range(t):
        n = int(input[idx])
        a = int(input[idx+1])
        b = int(input[idx+2])
        idx += 3

        if can_reach_one(n, a, b):
            print("Yes")
        else:
            print("No")

if __name__ == "__main__":
    main()
"}

