def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        gangs = list(map(int, input().split()))

        # Map from gang ID to list of districts
        gang_to_districts = {}
        for i in range(n):
            gang = gangs[i]
            if gang not in gang_to_districts:
                gang_to_districts[gang] = []
            gang_to_districts[gang].append(i)

        # Union-Find data structure
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            pu = find(u)
            pv = find(v)
            if pu != pv:
                parent[pu] = pv

        roads = []
        connected = 0

        # Use one district from each gang as a hub
        hubs = []  # List of hub indices
        for gang in gang_to_districts:
            hubs.append(gang_to_districts[gang][0])

        # Connect all other districts to one of the hubs
        for i in range(n):
            if i in hubs:
                continue  # Skip hubs

            # Find a hub from a different gang
            found = False
            for hub in hubs:
                if gangs[i] != gangs[hub] and find(i) != find(hub):
                    union(i, hub)
                    roads.append((i+1, hub+1))  # 1-indexed
                    found = True
                    break
            if not found:
                # No valid connection found
                print("NO")
                break
            connected += 1

        else:
            # All districts connected
            print("YES")
            for road in roads:
                print(road[0], road[1])

solve()
