    """Count the number of spruces in the matrix"""
    count = 0

    # For each cell (i, j)
    for i in range(n):
        for j in range(m):
            if matrix[i][j] == '*':
                # Check all possible heights
                max_height = min(i, n - i - 1, j, m - j) + 1
                for k in range(1, max_height + 1):
                    # Check if this cell can be the origin of a spruce of height k
                    is_valid = True

                    # For each row from i to i + k - 1
                    for row in range(i, i + k):
                        # The columns in this row should be from j - (row - i) to j + (row - i)
                        start_col = j - (row - i)
                        end_col = j + (row - i)

                        # Check if all these columns are '*'
                        for col in range(start_col, end_col + 1):
                            if matrix[row][col] != '*':
