from collections import defaultdict, deque

def solve():
    n, m, T = map(int, input().split())

    # Build adjacency list
    graph = defaultdict(list)
    for _ in range(m):
        u, v, t = map(int, input().split())
        graph[u].append((v, t))

    # Topological sort using Kahn's algorithm
    in_degree = [0] * (n + 1)
    for u in graph:
        for v, _ in graph[u]:
            in_degree[v] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    top_order = []
    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v, _ in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP: dp[v] is a dictionary {time: max_nodes}
    dp = [defaultdict(int) for _ in range(n + 1)]
    dp[1][0] = 1  # Start at node 1 with 0 time, visiting 1 node

    for u in top_order:
        if u == 1:
            continue  # Already initialized

        for v, w in graph[u]:
            for t, count in dp[u].items():
                if t + w <= T:
                    if dp[v][t + w] < count + 1:
                        dp[v][t + w] = count + 1

    # Find the maximum number of nodes to reach node n
    max_nodes = max(dp[n].values())
    best_time = None
    for t, count in dp[n].items():
        if count == max_nodes:
            best_time = t
            break

    # Reconstruct path
    path = []
    current = n
    current_time = best_time

    while current != 1:
        for v, w in graph[current]:
            if dp[current][current_time] == dp[v][current_time - w] + 1:
                path.append(current)
                current = v
                current_time -= w
                break

    path.append(1)
    path.reverse()

    print(len(path))
    print(' '.join(map(str, path)))

solve()
