        u = queue.popleft()
        top_order.append(u)
        for v, _ in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP: dp[v][k] = minimum time to reach node v with exactly k nodes
    INF = float('inf')
    dp = [[INF] * (n + 1) for _ in range(n + 1)]
    dp[1][1] = 0  # Start at node 1 with 1 node and 0 time

    for u in top_order:
        for k in range(1, n + 1):
            if dp[u][k] == INF:
                continue
            # Propagate to all neighbors
            for v, w in graph[u]:
                if dp[v][k + 1] > dp[u][k] + w:
                    dp[v][k + 1] = dp[u][k] + w

