def is_increasing(matrix, n, m):
    # Check if all rows are strictly increasing
    for i in range(n):
        for j in range(1, m):
            if matrix[i][j] <= matrix[i][j-1]:
                return False

    # Check if all columns are strictly increasing
    for j in range(m):
        for i in range(1, n):
            if matrix[i][j] <= matrix[i-1][j]:
                return False

    return True

def solve():
    n, m = map(int, input().split())

    # Read first matrix
    a = []
    for _ in range(n):
        a.append(list(map(int, input().split())))

    # Read second matrix
    b = []
    for _ in range(n):
        b.append(list(map(int, input().split())))

    # Try both possibilities for each position
    # Option 1: Keep a as first matrix, b as second matrix
    matrix_a1 = [row[:] for row in a]
    matrix_b1 = [row[:] for row in b]

    # Option 2: Swap a and b
    matrix_a2 = [row[:] for row in b]
    matrix_b2 = [row[:] for row in a]

    # Check if either option works
    if is_increasing(matrix_a1, n, m) and is_increasing(matrix_b1, n, m):
        print("Possible")
    elif is_increasing(matrix_a2, n, m) and is_increasing(matrix_b2, n, m):
        print("Possible")
    else:
        print("Impossible")

