def is_increasing(matrix, n, m):
    # Check if all rows are strictly increasing
    for i in range(n):
        for j in range(1, m):
            if matrix[i][j] <= matrix[i][j-1]:
                return False

    # Check if all columns are strictly increasing
    for j in range(m):
        for i in range(1, n):
            if matrix[i][j] <= matrix[i-1][j]:
                return False

    return True

