import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    h = int(data[1])

    intervals = []
    idx = 2
    for _ in range(n):
        x1 = int(data[idx])
        x2 = int(data[idx+1])
        intervals.append((x1, x2))
        idx += 2

    # Brute-force for understanding
    max_distance = 0

    # Try starting at various points
    # Try points near the start of the first interval
    for start in range(intervals[0][0] - 10, intervals[0][0] + 10):
        # Try ending at various points
        for end in range(intervals[-1][1] - 10, intervals[-1][1] + 10):
            # Calculate total descent
            descent = 0
            prev = start
            for i in range(len(intervals) + 1):
                if i == len(intervals):
                    curr = end
                else:
                    # Check if we're within the current interval
                    if prev >= intervals[i][0] and prev <= intervals[i][1]:
                        # We're inside the interval, so we stay at altitude
                        pass
                    else:
                        # We need to descend to/through this interval
                        if prev < intervals[i][0]:
                            # Descend from prev to the start of the interval
                            descent += intervals[i][0] - prev
                        elif prev > intervals[i][1]:
                            # Descend from the end of the interval to prev
                            descent += prev - intervals[i][1]

                prev = curr

            # Check if descent is within limit
            if descent <= h:
                max_distance = max(max_distance, end - start)

    print(max_distance)

if __name__ == "__main__":
    solve()
