n, m, s, t = map(int, input().split())

roads = []

for _ in range(m):
    u, v, w = map(int, input().split())
    roads.append((u, v, w))

# Build graph
from collections import defaultdict

graph = defaultdict(list)

for u, v, w in roads:
    graph[u].append((v, w))

# Dijkstra from s to all
import heapq

d_from_s = [float('inf')] * (n + 1)
d_from_s[s] = 0
heap = [(0, s)]

done = [False] * (n + 1)
while heap:
    dist_u, u = heapq.heappop(heap)
    if done[u]:
        continue
    done[u] = True

    for v, w in graph[u]:
        if d_from_s[v] > d_from_s[u] + w:
            d_from_s[v] = d_from_s[u] + w
            heapq.heappush(heap, (d_from_s[v], v))

# Dijkstra from t to all

d_from_t = [float('inf')] * (n + 1)
d_from_t[t] = 0
heap = [(0, t)]

done = [False] * (n + 1)
while heap:
    dist_u, u = heapq.heappop(heap)
    if done[u]:
        continue
    done[u] = True

    for v, w in graph[u]:
        if d_from_t[v] > d_from_t[u] + w:
            d_from_t[v] = d_from_t[u] + w
            heapq.heappush(heap, (d_from_t[v], v))

# Process each road
for u, v, w in roads:

    if d_from_s[u] + w + d_from_t[v] == d_from_s[t]:
        print("YES")
    else:
        # Check if we can repair it
        required_weight = d_from_s[t] - d_from_s[u] - d_from_t[v]
        if required_weight > 0:
            cost = abs(w - required_weight)
            print(f"CAN {cost}")
        else:
            print("NO")
