    # Find how many players have a result strictly greater than best_result
    better_players = 0
    for result in results:
        if result > best_result:
            better_players += 1

    # Calculate percentile
    percentile = (better_players / len(results)) * 100

    # Determine category
    if percentile > 50:
        category = "noob"
    elif 20 < percentile <= 50:
        category = "random"
    elif 10 < percentile <= 80:
        category = "average"
    elif 1 < percentile <= 90:
        category = "hardcore"
    else:
        category = "pro"

    output.append(f"{name} {category}")

# Print output
print(len(output))
for line in output:
    print(line)
