    idx = 0
    n = int(data[idx])
    idx += 1
    m = int(data[idx])
    idx += 1

    # Build adjacency list and in-degree count
    adj = [[] for _ in range(n)]
    in_degree = [0] * n

    for _ in range(m):
        u = int(data[idx]) - 1
        idx += 1
        v = int(data[idx]) - 1
        idx += 1

        adj[u].append(v)
        in_degree[v] += 1

    # Check if the graph has a cycle using Kahn's algorithm
    queue = []
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    top_order = []
    while queue:
        u = queue.pop(0)
        top_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(top_order) != n:
        print(-1)
        return

    # Now we have a topological order
    # We want to assign A (forall) to as many as possible
    # For a variable to be A, all edges must go out (sink) or all edges must go in (source)

    # Count how many variables are sinks (all edges go out)
    # Count how many variables are sources (all edges go in)
    sinks = 0
    sources = 0

    for i in range(n):
        # Check if all edges go out from i (sink)
        is_sink = True
        for v in adj[i]:
            if v == top_order.index(i):  # Check if the edge goes out from i
                pass
            else:
                is_sink = False
                break
        if is_sink:
            sinks += 1

        # Check if all edges go into i (source)
        is_source = True
        for u in range(n):
            if u == i:
                continue
            for v in adj[u]:
                if v == i:
                    pass
                else:
                    is_source = False
                    break
            if not is_source:
                break
        if is_source:
            sources += 1

    # We can assign A to sinks and sources, but we need to be careful
    # Because a variable can be both sink and source (no edges)

    # Let's try to assign A greedily
    # We want to maximize the number of A's, so we should assign A to sinks and sources

    result = ['E'] * n

    # Assign A to sinks
    for i in range(n):
        if sinks > 0:
            is_sink = True
            for v in adj[i]:
                if v != top_order.index(i):  # Check if the edge goes out from i
                    is_sink = False
                    break
            if is_sink:
                result[i] = 'A'
                sinks -= 1

    # Assign A to sources
    for i in range(n):
        if sources > 0:
