def is_convex_polygon(points):
    """Check if all points are on the convex hull (i.e., no point is inside the convex hull of the others)."""
    if len(points) <= 3:
        return True

    # Compute convex hull
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Graham scan
    points = sorted(points)
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    convex_hull = lower[:-1] + upper[:-1]

    # Check if all points are on the convex hull
    return len(convex_hull) == len(points)

