                elif a1 == -1:
                    diff = max(diff, abs(a2 - k), abs(k - a1))
                elif a2 == -1:
                    diff = max(diff, abs(a1 - k), abs(k - a2))
                else:
                    diff = max(diff, abs(a1 - a2))

            if diff < min_diff:
