from sys import stdin, stdout
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        p = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Generate all edges
        edges = []

        # Consecutive edges
        for i in range(n - 1):
            edges.append((p, i, i + 1))

        # Non-consecutive edges
        for i in range(n):
            min_val = a[i]
            for j in range(i + 1, n):
                min_val = min(min_val, a[j])
                if find_gcd(a[i:j+1]) == min_val:
                    edges.append((min_val, i, j))
                else:
                    break

        # Prim's algorithm
        import heapq

        # Build adjacency list
        adj = [[] for _ in range(n)]
        for w, u, v in edges:
            adj[u].append((w, v))
            adj[v].append((w, u))

        # Prim's algorithm
        visited = [False] * n
        min_heap = [(0, 0)]  # (weight, vertex)
        total_weight = 0

        while min_heap:
            w, u = heapq.heappop(min_heap)
            if visited[u]:
                continue
            visited[u] = True
            total_weight += w

            for neighbor_weight, v in adj[u]:
                if not visited[v]:
                    heapq.heappush(min_heap, (neighbor_weight, v))

        out_lines.append(str(total_weight))

    stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
