def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        p = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Generate all edges
        edges = []

        # Consecutive edges
        for i in range(n - 1):
            edges.append((p, i, i + 1))

        # Non-consecutive edges
        for i in range(n):
            for j in range(i + 1, n):
                sub = a[i:j+1]
                if find_gcd(sub) == find_min(sub):
                    edges.append((find_min(sub), i, j))

        # Kruskal's algorithm
        edges.sort()
        parent = list(range(n))
        rank = [1] * n

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            u_root = find(u)
            v_root = find(v)
            if u_root == v_root:
                return False
            if rank[u_root] < rank[v_root]:
                parent[u_root] = v_root
            else:
