def combination(n, k):
    """Calculate n choose k"""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    result = 1
    for i in range(1, k + 1):
        result = result * (n - i + 1) // i
    return result

n, m, h = map(int, input().split())
s = list(map(int, input().split()))

# Check if we can form the team
if sum(s) < n:
    print(-1)
else:
    # Special case: n=1 means only Herr Wafa on the team, so no teammates
    if n == 1:
        print(0)
    else:
        # Calculate probability
        sh = s[h - 1]  # Herr Wafa's department has sh players
        players_not_in_h = sum(s) - sh

        # We need to choose n-1 players from the remaining sum(s) - 1 players
        # The number of ways to choose all n-1 players from other departments
        ways_all_other = combination(players_not_in_h, n - 1)

        # Total ways to choose n-1 players from the remaining
        total_ways = combination(sum(s) - 1, n - 1)

        # Probability of at least one teammate from Herr Wafa's department
        probability = 1 - (ways_all_other / total_ways)

        # Format output
        if probability == 1:
            print(1)
        elif probability == 0:
            print(0)
        else:
            print(f"{probability:.10f}")
"}

