def find_valid_suffixes(s):
    n = len(s)
    valid_suffixes = set()

    # Try all possible root lengths (at least 5 characters)
    for root_length in range(5, n):
        suffix_start = root_length
        suffix_part = s[suffix_start:]  # The part that could be suffixes

        # Find all valid suffix sequences for this suffix part
        # We need to split the suffix part into suffixes of length 2 or 3
        # without consecutive duplicates

        # Use dynamic programming to find valid suffix sequences
        # dp[i] = set of valid suffix sequences for the first i characters
        dp = [set() for _ in range(len(suffix_part) + 1)]
        dp[0].add(())  # Empty sequence

        for i in range(len(suffix_part)):
            for seq in dp[i]:
                # Try adding a suffix of length 2
                if i + 2 <= len(suffix_part):
                    suffix_2 = suffix_part[i:i+2]
                    if not seq or seq[-1] != suffix_2:
                        dp[i+2].add(seq + (suffix_2,))

                # Try adding a suffix of length 3
                if i + 3 <= len(suffix_part):
                    suffix_3 = suffix_part[i:i+3]
                    if not seq or seq[-1] != suffix_3:
                        dp[i+3].add(seq + (suffix_3,))

        # Collect all valid suffixes from all valid sequences
        for seq in dp[len(suffix_part)]:
            for suffix in seq:
                valid_suffixes.add(suffix)

    return sorted(valid_suffixes)

