def find_valid_suffixes(s):
    n = len(s)
    valid_suffixes = set()

    # Try all possible root lengths (at least 5 characters)
    for root_length in range(5, n):
        suffix_start = root_length
        suffix_part = s[suffix_start:]  # The part that could be suffixes

        # Try all possible suffix sequences for this suffix part
        # Use recursive backtracking with memoization

        memo = {}

        def backtrack(start, last_suffix):
            if start == len(suffix_part):
                return []

            # Memoization
            key = (start, last_suffix)
            if key in memo:
                return memo[key]

            # Try adding a suffix of length 2
            result = []
            if start + 2 <= len(suffix_part):
                suffix_2 = suffix_part[start:start+2]
                if last_suffix != suffix_2:
                    subseq = backtrack(start + 2, suffix_2)
                    if subseq:
                        result.append(suffix_2 + ''.join(subseq))

            # Try adding a suffix of length 3
            if start + 3 <= len(suffix_part):
                suffix_3 = suffix_part[start:start+3]
                if last_suffix != suffix_3:
                    subseq = backtrack(start + 3, suffix_3)
                    if subseq:
                        result.append(suffix_3 + ''.join(subseq))

            # Return all valid sequences starting from this position
            memo[key] = result
            return result

        # Find all valid suffix sequences starting from position 0 with no previous suffix
        sequences = backtrack(0, None)

        # Collect all distinct suffixes
        for seq in sequences:
            for i, suffix in enumerate(seq):
                valid_suffixes.add(suffix)

    return sorted(valid_suffixes)

