def intersect(x1, y1, x2, y2):
    # Check if semi-circles from (x1,0) to (y1,0) and from (x2,0) to (y2,0) intersect
    a, b = sorted([x1, y1])
    c, d = sorted([x2, y2])

    overlap_start = max(a, c)
    overlap_end = min(b, d)

    if overlap_start >= overlap_end:
        return False

    # Check if they intersect (not just touch)
    # Return True if they intersect
    return not (overlap_start == a and overlap_end == b) and not (overlap_start == c and overlap_end == d)

