{"code": "
def is_convex(grid, n, m):
    # Find all black cells
    black_cells = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == 'B']

    # Check if all pairs of black cells have a valid path
    for i in range(len(black_cells)):
        for j in range(i + 1, len(black_cells)):
            x1, y1 = black_cells[i]
            x2, y2 = black_cells[j]

            # Check path: horizontal first, then vertical
            valid = False

            # Try all possible turning points horizontally
            for y_turn in range(min(y1, y2), max(y1, y2) + 1):
                # Check horizontal segment from (x1, y1) to (x1, y_turn)
                if all(grid[x1][y] == 'B' for y in range(min(y1, y_turn), max(y1, y_turn) + 1)):
                    # Check vertical segment from (x1, y_turn) to (x2, y2)
                    if all(grid[x][y_turn] == 'B' for x in range(min(x1, x2), max(x1, x2) + 1)):
                        valid = True
                        break

            if not valid:
                # Check path: vertical first, then horizontal
                for x_turn in range(min(x1, x2), max(x1, x2) + 1):
                    # Check vertical segment from (x1, y1) to (x_turn, y1)
