import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        xor_sum = 0

        for r in range(1, n + 1):
            for c in range(1, m + 1):
                val = int(next(it))
                # Calculate Grundy number: value * (n-r+1) * (m-c+1)
                grundy = val * (n - r + 1) * (m - c + 1)
                xor_sum ^= grundy

        if xor_sum != 0:
            print("Ashish")
        else:
            print("Jeel")

if __name__ == "__main__":
    solve()
