def is_in_set(n, a, b, memo):
    if n == 1:
        return True

    # Check if we've already computed this
    if n in memo:
        return memo[n]

    result = False

    # Check if we can reach n by multiplying
    if n % a == 0:
        result = is_in_set(n // a, a, b, memo)

    # Check if we can reach n by adding
    if not result and n >= b:
        result = is_in_set(n - b, a, b, memo)

    memo[n] = result
    return result

