    # Try different values of k (how many times we multiply by a)
    # We can try up to log_a(n) + 1 values of k
    # Since a >= 1, we need to be careful with a=1
    found = False
    if a == 1:
        # If a=1, we can only add b repeatedly
        # So we need to check if (n-1) is divisible by b
        if (n - 1) % b == 0:
            found = True
    else:
        # Try different values of k
        # We can try up to 32 iterations (should be more than enough)
        for k in range(0, 32):  # Try up to 2^32 (should be more than enough)
            power = a ** k
            if power > n:
                break
            remainder = n - power
            if remainder >= 0 and remainder % b == 0:
                found = True
                break

    print("Yes" if found else "No")
