from collections import defaultdict, deque

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        # Build graph of districts with different gangs
        graph = defaultdict(list)
        for i in range(n):
            for j in range(i + 1, n):
                if a[i] != a[j]:
                    graph[i].append(j)
                    graph[j].append(i)

        # Check connectivity using BFS
        visited = [False] * n
        queue = deque()
        queue.append(0)
        visited[0] = True

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        if all(visited):
            print("YES")
            # Build spanning tree using BFS
            spanning_tree = []
            visited = [False] * n
            queue = deque()
            queue.append(0)
            visited[0] = True

            while queue:
                node = queue.popleft()
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        spanning_tree.append((node + 1, neighbor + 1))  # 1-indexed
                        queue.append(neighbor)

            for u, v in spanning_tree:
                print(u, v)
        else:
            print("NO")

solve()
