        row = list(input().strip())
        grid.append(row)

        # Find start and exit positions
        for j in range(c):
            if row[j] == 'S':
                start_pos = (i, j)
            if row[j] == 'E':
                exit_pos = (i, j)

    # BFS to find shortest path from start to exit
    dist_start = [[-1] * c for _ in range(r)]
    q = deque()
    q.append((start_pos[0], start_pos[1]))
    dist_start[start_pos[0]][start_pos[1]] = 0

    while q:
        x, y = q.popleft()

        # Check all four directions
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy

            # Check if within bounds and not a tree
            if 0 <= nx < r and 0 <= ny < c and grid[nx][ny] != 'T':
                if dist_start[nx][ny] == -1:
                    dist_start[nx][ny] = dist_start[x][y] + 1
                    q.append((nx, ny))

    # Calculate distance from start to exit
    start_dist_to_exit = dist_start[exit_pos[0]][exit_pos[1]]

    # BFS from each breeder to exit
    max_battles = 0

