import math

A, B, C = map(int, input().split())

if A == 0:
    if B == 0:
        if C == 0:
            print(-1)  # Infinite solutions
        else:
            print(0)   # No solution
    else:
        # Linear equation: Bx + C = 0
        x = -C / B
        print(1)
        print(f"{x:.5f}")
else:
    # Quadratic equation
    D = B * B - 4 * A * C

    if D < 0:
        print(0)
    elif D == 0:
        x = -B / (2 * A)
        print(1)
        print(f"{x:.5f}")
    else:
        # Two distinct roots
        sqrt_D = math.sqrt(D)
        x1 = (-B - sqrt_D) / (2 * A)
        x2 = (-B + sqrt_D) / (2 * A)

        # Ensure ascending order
        if x1 > x2:
            x1, x2 = x2, x1

        print(2)
        print(f"{x1:.5f}")
        print(f"{x2:.5f}")
"}

