import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    grid = []
    idx = 2
    for _ in range(n):
        row = data[idx:idx+m]
        grid.append(row)
        idx += m

    # find boundaries
    left = m  # index
    right = -1
    top = n
    bottom = -1

    black_cells = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'B':
                black_cells.append((i, j))
                left = min(left, j)
                right = max(right, j)
                top = min(top, i)
                bottom = max(bottom, i)

    if not black_cells:
        print('YES')
        return

    # check if all in one row
    all_in_one_row = True
    first_row = black_cells[0][0]
    for (i, j) in black_cells:
        if i != first_row:
            all_in_one_row = False
            break
    if all_in_one_row:
        print('YES')
        return

    # check if all in one column
    all_in_one_col = True
    first_col = black_cells[0][1]
    for (i, j) in black_cells:
        if j != first_col:
            all_in_one_col = False
            break
    if all_in_one_col:
        print('YES')
        return

    # check inner cells
    inner = []
    for (i, j) in black_cells:
        if not (i == top or i == bottom or j == left or j == right):
            inner.append((i, j))

    if not inner:
        print('YES')
        return

    # inner cells must all lie on the same row or same column
    # i.e., they form a vertical or horizontal strip inside the rectangle
    first_inner_i = inner[0][0]
    first_inner_j = inner[0][1]
    all_same_row = True
    all_same_col = True
    for (i, j) in inner:
        if i != first_inner_i:
            all_same_row = False
        if j != first_inner_j:
            all_same_col = False
        if not all_same_row and not all_same_col:
            break
    if all_same_row or all_same_col:
        print('YES')
    else:
        print('NO')

if __name__ == '__main__':
    solve()
