# Set to store valid suffixes
valid_suffixes = set()

# Try different root lengths
for root_end in range(5, n):  # root starts at 0, ends at root_end (exclusive)
    suffix_start = root_end
    suffix_part = s[suffix_start:]  # The part that must be suffixes

    # Try all possible ways to split the suffix_part
    # Use DP: dp[i] = set of valid suffixes sequences ending at position i
    m = len(suffix_part)
    dp = [set() for _ in range(m + 1)]
    dp[0] = {()}  # Empty sequence

    for i in range(m):
        if i + 2 <= m:
            suffix_len2 = suffix_part[i:i+2]
            for prev_seq in dp[i]:
                if not prev_seq or prev_seq[-1] != suffix_len2:
                    new_seq = prev_seq + (suffix_len2,)
                    dp[i+2].add(new_seq)
        if i + 3 <= m:
            suffix_len3 = suffix_part[i:i+3]
            for prev_seq in dp[i]:
                if not prev_seq or prev_seq[-1] != suffix_len3:
                    new_seq = prev_seq + (suffix_len3,)
                    dp[i+3].add(new_seq)

    # Extract all valid suffixes from sequences that reach the end
    for seq in dp[m]:
        valid_suffixes.update(seq)

# Output results
print(len(valid_suffixes))
for suffix in sorted(valid_suffixes):
    print(suffix)
