def is_consecutive_fibonacci(a, b):
    """Check if a and b are consecutive Fibonacci numbers with a <= b"""
    if a == 0:
        return b == 1

    # Generate Fibonacci numbers up to max(a, b)
    fib = [0, 1]
    while fib[-1] < max(a, b):
        fib.append(fib[-1] + fib[-2])

    # Check if b is the next Fibonacci number after a
    try:
        idx = fib.index(a)
        if idx + 1 < len(fib) and fib[idx + 1] == b:
            return True
    except ValueError:
        pass

    return False

def solve():
    t = int(input())
    for _ in range(t):
        a, b = map(int, input().split())

        if a == 0 or b == 0:
            # At least one is zero, first player can't move
            print("Second")
        elif a > b:
            # Only possible move is b mod a = b, which doesn't change the position
            print("Second")
        else:
            # Check if a and b are consecutive Fibonacci numbers
            if is_consecutive_fibonacci(a, b):
                print("Second")
            else:
                print("First")

solve()
