def brute_force(n, p, a):
    # Generate all possible edges
    edges = []

    # Add adjacent edges
    for i in range(n - 1):
        edges.append((p, i, i + 1))

    # Add non-adjacent edges that satisfy the condition
    for i in range(n):
        for j in range(i + 1, n):
            subarray = a[i:j+1]
            min_val = min(subarray)
            gcd_val = subarray[0]
            for val in subarray[1:]:
                gcd_val = math.gcd(gcd_val, val)
            if gcd_val == min_val:
                edges.append((min_val, i, j))

    # Sort edges
    edges.sort()

    # Kruskal's algorithm
    parent = list(range(n))

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        pu = find(u)
        pv = find(v)
        if pu == pv:
            return False
        parent[pu] = pv
        return True

    total_weight = 0
    count = 0

    for weight, u, v in edges:
        if union(u, v):
            total_weight += weight
            count += 1
            if count == n - 1:
                break

    return total_weight


t = int(input())
for _ in range(t):
    n, p = map(int, input().split())
    a = list(map(int, input().split()))
    print(brute_force(n, p, a))
