t = int(input())
for _ in range(t):
    n = int(input())
    a = list(map(int, input().split()))

    # Find a gang that appears at least twice
    gang_count = {}
    gang_to_districts = {}

    for i in range(n):
        gang = a[i]
        gang_count[gang] = gang_count.get(gang, 0) + 1
        gang_to_districts[gang] = gang_to_districts.get(gang, []) + [i + 1]  # 1-indexed

    # Check if it's impossible
    if any(count < 2 for count in gang_count.values()):
        print("NO")
    else:
        # Pick a gang with count >= 2
        root_gang = next(gang for gang in gang_count if gang_count[gang] >= 2)
        root_district = gang_to_districts[root_gang][0]

        print("YES")

        # Connect all other districts to root
        for i in range(n):
            if i + 1 == root_district:
                continue
            if a[i] != a[root_district - 1]:
                # Different gang, connect directly to root
                print(f"{i + 1} {root_district}")
            else:
                # Same gang, connect to another district from the same gang
                # Find another district from this gang
                other_district = gang_to_districts[root_gang][1]
                print(f"{i + 1} {other_district}")
"}

