import math

def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def is_square(points):
    dists = []
    for i in range(len(points)):
        for j in range(i+1, len(points)):
            dists.append(distance(points[i], points[j]))

    dists.sort()
    # We should have 4 sides (shorter distance) and 2 diagonals (longer distance)
    if len(dists) != 6:
        return False

    # Check if we have 4 of one distance and 2 of another
    if dists[0] == dists[1] == dists[2] == dists[3] and dists[4] == dists[5]:
        side = dists[0]
        diag = dists[4]
        # Check if diagonal is side * sqrt(2)
        return math.isclose(diag, side * math.sqrt(2), rel_tol=1e-9)

    return False

def is_rectangle(points):
    dists = []
    for i in range(len(points)):
        for j in range(i+1, len(points)):
            dists.append(distance(points[i], points[j]))

    dists.sort()
    # We should have 2 sides (each appearing 2 times) and 2 diagonals
    if len(dists) != 6:
        return False

    from collections import Counter
    cnt = Counter(dists)

    # Check if we have 2 pairs of equal distances and one other
    if len(cnt) == 3:
        # We have 3 distinct distances
        # Check if two are sides and one is diagonal
        # The diagonal should satisfy Pythagorean theorem
        sides = []
        for d, c in cnt.items():
            if c == 2:
                sides.append(d)

        if len(sides) == 2:
            side1, side2 = sides
            # Find the diagonal (appears 2 times)
            diagonal = [d for d in cnt if cnt[d] == 2][0]
            return math.isclose(diagonal, math.sqrt(side1**2 + side2**2), rel_tol=1e-9)

    return False

def solve():
    points = []
    for i in range(8):
        x, y = map(int, input().split())
        points.append((x, y))

    # Try all combinations of 4 points for the square
    from itertools import combinations

    for square_indices in combinations(range(8), 4):
        square_points = [points[i] for i in square_indices]
        if is_square(square_points):
            rectangle_points = [points[i] for i in range(8) if i not in square_indices]
            if is_rectangle(rectangle_points):
                # Output the result
                print("YES")
                print(" ".join(map(str, [i+1 for i in square_indices])))
                print(" ".join(map(str, [i+1 for i in range(8) if i not in square_indices])))
                return

    print("NO")

solve()
