from collections import deque

def solve():
    # Read input
    a1, b1 = map(int, input().split())
    a2, b2 = map(int, input().split())

    # BFS to find minimum minutes
    # Each state is (a1, b1, a2, b2, minutes)
    queue = deque([(a1, b1, a2, b2, 0)])
    visited = set()
    visited.add((a1, b1, a2, b2))

    while queue:
        a, b, a2, b2, minutes = queue.popleft()

        # Check if equal
        if a * b == a2 * b2:
            print(minutes)
            print(a, b)
            print(a2, b2)
            return

        # Apply operations to first bar
        if a % 2 == 0:
            if (a//2, b, a2, b2) not in visited:
                visited.add((a//2, b, a2, b2))
                queue.append((a//2, b, a2, b2, minutes + 1))
        if b % 2 == 0:
            if (a, b//2, a2, b2) not in visited:
                visited.add((a, b//2, a2, b2))
                queue.append((a, b//2, a2, b2, minutes + 1))

        if a % 3 == 0:
            if (2*a//3, b, a2, b2) not in visited:
                visited.add((2*a//3, b, a2, b2))
                queue.append((2*a//3, b, a2, b2, minutes + 1))
