import sys

def determine_category(percentile):
    """Determine category based on percentile"""
    if percentile > 50:
        return "noob"
    elif 20 < percentile <= 50:
        return "random"
    elif 10 < percentile <= 80:
        return "average"
    elif 1 < percentile <= 90:
        return "hardcore"
    else:
        return "pro"

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    n = int(data[0])
    players = []

    for i in range(1, n + 1):
        name, points = data[i].split()
        points = int(points)
        players.append((name, points))

    # Find best result for each player
    best_results = {}
    for name, points in players:
        best_results[name] = max(best_results.get(name, 0), points)

    # Get sorted list of best results
    sorted_results = sorted(best_results.values())

    # Determine category for each player
    results = []
    for name, points in best_results.items():
        # Find percentile
        rank = sorted_results.index(points) + 1  # 1-indexed
        percentile = (rank / len(sorted_results)) * 100

        # Handle case where multiple players have the same result
        # We need to consider ties
        if percentile > 50:
            results.append((name, "noob"))
        elif 20 < percentile <= 50:
            results.append((name, "random"))
        elif 10 < percentile <= 80:
            results.append((name, "average"))
        elif 1 < percentile <= 90:
            results.append((name, "hardcore"))
        else:
            results.append((name, "pro"))

    # Sort by name
    results.sort()

    # Print output
    print(len(results))
    for name, category in results:
        print(f"{name} {category}")

if __name__ == "__main__":
    main()
"}

