n, m = map(int, input().split())

# Build adjacency list
adj = [[] for _ in range(n)]

for _ in range(m):
    j, k = map(int, input().split())
    j -= 1  # Convert to 0-indexed
    k -= 1
    adj[j].append(k)

# Find strongly connected components (SCCs)
# If there's a cycle, output -1
# For DAGs, we need to assign quantifiers carefully

visited = [False] * n
order = []

def dfs1(u):
    visited[u] = True
    for v in adj[u]:
        if not visited[v]:
            dfs1(v)
    order.append(u)

for i in range(n):
    if not visited[i]:
        dfs1(i)

# Transpose graph
adj_t = [[] for _ in range(n)]
for u in range(n):
    for v in adj[u]:
        adj_t[v].append(u)

visited = [False] * n
scc = []

def dfs2(u, component):
    visited[u] = True
    component.append(u)
    for v in adj_t[u]:
        if not visited[v]:
            dfs2(v, component)

for u in reversed(order):
    if not visited[u]:
        component = []
        dfs2(u, component)
        scc.append(component)

# If any SCC has size > 1, it's a cycle
if any(len(component) > 1 for component in scc):
    print(-1)
else:
    # Now we have a DAG
    # Let's topologically sort
    in_degree = [0] * n
    for u in range(n):
        for v in adj[u]:
            in_degree[v] += 1

    queue = [i for i in range(n) if in_degree[i] == 0]
top_order = []

    while queue:
        u = queue.pop(0)
top_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(top_order) != n:
        print(-1)
    else:
        # Assign quantifiers
        # If out_degree[i] == 0, we can set x_i to be arbitrarily large -> 'A'
        # If in_degree[i] == 0, we can set x_i to be arbitrarily small -> 'E'
        # If both > 0, prefer 'A' if possible, else 'E'

