            if out_degree[i] == 0:
                result.append('A')
            elif in_degree[i] == 0:
                result.append('E')
            else:
                # Both > 0, prefer 'A'
                result.append('A')

        print(len([c for c in result if c == 'A']))
        print(''.join(result))
