def cross(o, a, b):
    """Calculate cross product of vectors OA and OB."""
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def convex_hull(points):
    """Find the convex hull of a set of points using Andrew's monotone chain algorithm."""
    if not points:
        return []
    if len(points) == 1:
        return points

    points = sorted(points)
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    # Remove the last point of each half, which is the same as the first point of the other half
    return lower[:-1] + upper[:-1]

def solve():
    import sys
    input = sys.stdin.read().split()
    data = list(map(int, input))

    if not data:
        return

    n = data[0]
    m = data[1]

    points1 = []
    idx = 2
    for _ in range(n):
        x = data[idx]
        y = data[idx + 1]
        points1.append((x, y))
        idx += 2

    points2 = []
    for _ in range(m):
        x = data[idx]
        y = data[idx + 1]
        points2.append((x, y))
        idx += 2

    hull1 = convex_hull(points1)
    hull2 = convex_hull(points2)

    # If both have exactly 3 vertices, they are always "safe"
    if len(hull1) == 3 and len(hull2) == 3:
        print("YES")
    else:
        # Check if both have the same number of vertices (and they're both convex)
        if len(hull1) == len(hull2):
            print("YES")
        else:
            print("NO")

solve()
