n, m, s, t = map(int, input().split())

# Build graph
graph = [[] for _ in range(n + 1)]
for _ in range(m):
    a, b, l = map(int, input().split())
    graph[a].append((b, l))

# Compute shortest distances from s to all nodes (d_s)
d_s = [float('inf')] * (n + 1)
d_s[s] = 0
import heapq
heap = [(0, s)]
while heap:
    dist, node = heapq.heappop(heap)
    if dist > d_s[node]:
        continue
    for neighbor, weight in graph[node]:
        if d_s[neighbor] > d_s[node] + weight:
            d_s[neighbor] = d_s[node] + weight
            heapq.heappush(heap, (d_s[neighbor], neighbor))

# Compute shortest distances from all nodes to t (d_t)
# Reverse the graph and compute from t
reversed_graph = [[] for _ in range(n + 1)]
for a in range(1, n + 1):
    for b, l in graph[a]:
        reversed_graph[b].append((a, l))

d_t = [float('inf')] * (n + 1)
d_t[t] = 0
heap = [(0, t)]
while heap:
    dist, node = heapq.heappop(heap)
    if dist > d_t[node]:
        continue
    for neighbor, weight in reversed_graph[node]:
        if d_t[neighbor] > d_t[node] + weight:
            d_t[neighbor] = d_t[node] + weight
            heapq.heappush(heap, (d_t[neighbor], neighbor))

# Process each road
for _ in range(m):
    a, b, l = map(int, input().split())
    required = d_s[t] - d_s[a] - d_t[b]

    if required == l:
        print("YES")
    elif required > 0:
        # Need to repair to length required
        cost = abs(l - required)
        print(f"CAN {cost}")
    else:
        print("NO")
