def topological_sort(n, adj):
    in_degree = [0] * (n + 1)
    for u in range(1, n + 1):
        for v in adj[u]:
            in_degree[v] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    topo_order = []
    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    return topo_order

def solve():
    n, m, T = map(int, input().split())

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v, t = map(int, input().split())
        adj[u].append((v, t))

    # Topological sort
    topo_order = topological_sort(n, adj)

    # For each node, keep track of min_time[k] = min time to reach node with k nodes visited
    # We'll use a dictionary of dictionaries
    min_time = {i: {1: 0} for i in range(1, n + 1)}  # min_time[node][k] = min time

    # Process nodes in topological order
    for u in topo_order:
        if u == 1:
            # Start at node 1 with 1 node visited and 0 time
            continue

        for (v, t) in adj[u]:
            # Try to extend paths to u to reach v
            for k in list(min_time[u].keys()):
                time_u = min_time[u][k]
                if time_u + t <= T:
                    if k + 1 not in min_time[v] or min_time[v][k+1] > time_u + t:
                        min_time[v][k+1] = time_u + t

    # Find maximum k such that min_time[n][k] <= T
    max_nodes = 1
    for k in range(2, n + 1):
        if k in min_time[n] and min_time[n][k] <= T:
            max_nodes = k

