    """Calculate the minimum number of operations to reduce area to target"""
    if area == target:
        return 0

    # Try breaking in half (area must be even)
    if area % 2 == 0:
        half_area = area // 2
        if half_area == target:
            return 1
        # Otherwise, continue searching from half_area

    # Try chipping off one third (area must be divisible by 3)
