def get_next_states(a, b):
    """Generate all possible next states after one operation"""
    next_states = []

    # Try breaking in half
    if a % 2 == 0:
        next_states.append((a // 2, b))
    if b % 2 == 0:
        next_states.append((a, b // 2))

    # Try chipping off a third
    if a % 3 == 0:
        next_states.append((2 * a // 3, b))
    if b % 3 == 0:
        next_states.append((a, 2 * b // 3))

    return next_states

# BFS to find minimum operations from start state to target area
def bfs(start_a, start_b, target_area):
    from collections import deque

    # Queue: (a, b, operations_count)
    queue = deque([(start_a, start_b, 0)])
    # Map: (a, b) -> operations_count
    visited = {(start_a, start_b): 0}

    while queue:
        a, b, ops = queue.popleft()

        # If we reach the target area, return the number of operations
        if a * b == target_area:
            return ops

        # Generate next states
