            for height in range(1, max_height + 1):
                # Check if a spruce of this height can exist at (i, j)
                valid = True

                # For each row in the spruce
                for r in range(height):
                    row = i + r
                    col_start = j - r
                    col_end = j + r

                    # Check all columns in this row
                    for col in range(col_start, col_end + 1):
                        if matrix[row][col] != '*':
