    """Count the number of spruces in the matrix"""
    count = 0

    # Try each cell as potential origin
    for i in range(n):
        for j in range(m):
            # Check for spruces of all possible heights
            max_height = min(n - i, m - j, i + 1)  # Can't go beyond matrix bounds
            for height in range(1, max_height + 1):
                # Check if a spruce of this height can exist at (i, j)
                valid = True

                # For each row in the spruce
                for r in range(height):
                    row = i + r
                    # Calculate column range for this row
                    col_start = j - height + r + 1
                    col_end = j + height - r - 1

                    # Check if columns are within bounds
                    if col_start < 0 or col_end >= m:
                        valid = False
                        break

                    # Check all columns in this row
                    for col in range(col_start, col_end + 1):
                        if matrix[row][col] != '*':
                            valid = False
                            break
                    if not valid:
                        break

                if valid:
                    count += 1

    return count

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        m = int(data[idx + 1])
        idx += 2

        matrix = []
        for _ in range(n):
            row = data[idx]
            matrix.append(row)
            idx += 1

        result = count_spruces(matrix, n, m)
        print(result)

if __name__ == "__main__":
    solve()
"}

