import sys
from math import gcd
from functools import reduce

def compute_gcd(arr):
    return reduce(gcd, arr)

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        p = int(data[idx+1])
        idx += 2

        a = list(map(int, data[idx:idx+n]))
        idx += n

        edges = []

        # Add adjacent edges
        for i in range(n - 1):
            edges.append((p, i, i + 1))

        # Add non-adjacent edges
        for i in range(n):
            for j in range(i + 2, n):
                # Check if GCD equals min
                subarray = a[i:j+1]
                min_val = min(subarray)
                gcd_val = compute_gcd(subarray)

                if gcd_val == min_val:
                    edges.append((min_val, i, j))

        # Kruskal's algorithm
        edges.sort()
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            px = find(x)
            py = find(y)
            if px == py:
                return False
            parent[py] = px
            return True

        total_weight = 0
        count = 0

        for w, u, v in edges:
            if count == n - 1:
                break
            if union(u, v):
                total_weight += w
                count += 1

        print(total_weight)

if __name__ == "__main__":
    solve()
"}

