    for _ in range(t):
        n, m = map(int, input().split())
        a = []
        for _ in range(n):
            row = list(map(int, input().split()))
            a.append(row)

        xor_sum = 0
        for i in range(n):
            for j in range(m):
                # Contribution factor: (number of rows below including current) * (number of columns to the right including current)
                contribution = a[i][j] * (n - i) * (m - j)
                xor_sum ^= contribution

        if xor_sum != 0:
            print("Ashish")
        else:
            print("Jeel")

solve()
