def calculate_center(K):
    center = (K + 1) // 2
    return center, center


def calculate_remoteness(row, col, center_row, center_col):
    return abs(row - center_row) + abs(col - center_col)


def solve() -> None:
    import sys
    data = sys.stdin.read().strip().split()

    if not data:
        return

    N = int(data[0])
    K = int(data[1])
    requests = list(map(int, data[2:2+N]))

    center_row, center_col = calculate_center(K)

    # Keep track of occupied seats
    occupied = [set() for _ in range(K + 1)]  # 1-indexed rows

    for i, M in enumerate(requests, 1):
        best_total = float('inf')
        best_row = -1
        best_yl = -1
        best_yr = -1

        # Try each row
        for row in range(1, K + 1):
            # Find all possible segments of M consecutive seats in this row
            for yl in range(1, K - M + 2):
                yr = yl + M - 1

                # Check if all seats in [yl, yr] are occupied
                if all(not occupied[row].contains(seat) for seat in range(yl, yr + 1)):
                    # Calculate total remoteness
                    total = 0
                    for seat in range(yl, yr + 1):
                        total += calculate_remoteness(row, seat, center_row, center_col)

                    # Update best if this is better
                    if total < best_total or \n                       (total == best_total and row < best_row) or \n                       (total == best_total and row == best_row and yl < best_yl):
                        best_total = total
                        best_row = row
                        best_yl = yl
                        best_yr = yr

        if best_row == -1:
            print(-1)
        else:
            print(f"{best_row} {best_yl} {best_yr}")

if __name__ == "__main__":
    solve()
"}

