def grundy(a, b):
    """Compute Grundy number for state (a, b)."""
    if a == 0 and b == 0:
        return 0
    if a == 0 or b == 0:
        return 1  # Terminal state, no moves possible
    # For a <= b
    if a > b:
        a, b = b, a
    # Possible moves: move to (a, r) where 0 < r < a
    next_states = set()
    # We can move to any state (a, r) where 0 < r < a
    for r in range(1, a):
        next_states.add(grundy(a, r))
    # Also consider modulus move
    modulus_move = grundy(a, b % a)
    next_states.add(modulus_move)
    # Grundy number is mex of next states
    mex = 0
    while mex in next_states:
        mex += 1
    return mex

t = int(input())
for _ in range(t):
    a, b = map(int, input().split())
    if grundy(a, b) != 0:
        print("First")
    else:
        print("Second")
