import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    S = int(data[0])
    a, b, c = int(data[1]), int(data[2]), int(data[3])

    # Create list of (exponent, variable)
    exponents = [(a, 'x'), (b, 'y'), (c, 'z')]

    # Sort by exponent (descending)
    exponents.sort(reverse=True, key=lambda x: x[0])

    # Group variables with the same exponent
    grouped = []
    current_exponent = None
    current_group = []

    for exp, var in exponents:
        if exp == current_exponent:
            current_group.append(var)
        else:
            if current_group:
                grouped.append((current_exponent, current_group))
            current_exponent = exp
            current_group = [var]

    if current_group:
        grouped.append((current_exponent, current_group))

    # Allocate S
    remaining = S

    for exponent, variables in grouped:
        if remaining == 0:
            break

        if exponent == 0:
            # This variable doesn't affect the distance, set to 0
            for var in variables:
                if var == 'x':
                    x = 0
                elif var == 'y':
                    y = 0
                elif var == 'z':
                    z = 0
            continue

        if exponent > 0:
            # Allocate remaining to this group
            n = len(variables)
            allocation = remaining / n

            for var in variables:
                if var == 'x':
                    x = allocation
                elif var == 'y':
                    y = allocation
                elif var == 'z':
                    z = allocation
            remaining = 0

    # Handle the case where exponent > 0 but we might not have allocated anything
    # This should only happen if exponent > 0 and remaining > 0, which we've handled

    print(f"{x} {y} {z}")

if __name__ == "__main__":
    solve()
"}

