n, k = map(int, input().split())

# Read guest preferences
preferences = []
for _ in range(k):
    x, y = map(int, input().split())
    preferences.append((x, y))

# Build graph: guest -> list of guests that should come after this guest
# (i.e., guests that need a snack also needed by this guest)
graph = [[] for _ in range(k)]

# Count how many guests need each snack
snack_count = [0] * (n + 1)
for i, (x, y) in enumerate(preferences):
    snack_count[x] += 1
    snack_count[y] += 1

# Build the graph
for i, (x, y) in enumerate(preferences):
    # If snack x is needed by multiple guests, create edges
    if snack_count[x] > 1:
        for j, (a, b) in enumerate(preferences):
            if j != i and a == x:
                graph[i].append(j)
    # If snack y is needed by multiple guests, create edges
    if snack_count[y] > 1:
        for j, (a, b) in enumerate(preferences):
            if j != i and b == y:
                graph[i].append(j)

# Find longest path using dynamic programming
# dp[i] = length of longest path ending at guest i
# We need to process guests in topological order

# Topological sort using Kahn's algorithm
in_degree = [0] * k
for i in range(k):
    for neighbor in graph[i]:
        in_degree[neighbor] += 1

# Queue for topological sort
queue = []
for i in range(k):
    if in_degree[i] == 0:
        queue.append(i)

# Process in topological order and compute longest path
topological_order = []
while queue:
    u = queue.pop(0)
    topological_order.append(u)
    for v in graph[u]:
        in_degree[v] -= 1
        if in_degree[v] == 0:
            queue.append(v)

# Compute longest path
dp = [1] * k
for u in topological_order:
    for v in graph[u]:
        dp[v] = max(dp[v], dp[u] + 1)

# The minimum number of sad guests is k - max(dp)
print(k - max(dp))
