def count_squares(n, m):
    """Count the number of distinct squares in an n×m table."""
    if n > m:
        n, m = m, n
    total = 0
    for k in range(1, n + 1):
        total += (n - k + 1) * (m - k + 1)
    return total

def solve(x):
    """Find all pairs (n, m) such that there are exactly x distinct squares."""
    results = []

    # Try all possible n values
    for n in range(1, int(x**0.5) + 1):
        # For each n, find m such that count_squares(n, m) = x
        # Since count_squares(n, m) increases with m, we can binary search
        low = 1
        high = 2 * x  # A safe upper bound
        while low <= high:
            mid = (low + high) // 2
            total = count_squares(n, mid)
            if total == x:
                results.append((n, mid))
                # Check if there's another solution
                low = mid + 1
            elif total < x:
                low = mid + 1
            else:
                high = mid - 1

    # Also try m values (which is the same as trying n values)
    for n in range(1, int(x**0.5) + 1):
        # Find m such that count_squares(m, n) = x
        low = 1
        high = 2 * x
        while low <= high:
            mid = (low + high) // 2
            total = count_squares(mid, n)
            if total == x:
                results.append((mid, n))
                low = mid + 1
            elif total < x:
                low = mid + 1
            else:
                high = mid - 1

    # Remove duplicates where n == m
    unique_results = set()
    for n, m in results:
        if n > m:
            n, m = m, n
        if (n, m) not in unique_results:
            unique_results.add((n, m))

    results = sorted(unique_results)

