    n = int(input())
    A = input().strip()
    B = input().strip()

    # Check if it's possible
    possible = True
    for a, b in zip(A, B):
        if a > b:
            possible = False
            break
    if not possible:
        print(-1)
        continue

    # Count how many positions need each transformation
    transform_count = {}
    for i in range(n):
        a = A[i]
        b = B[i]
        if a != b:
            transform_count[(a, b)] = transform_count.get((a, b), 0) + 1

    # Process from 'a' to 't'
    moves = 0

    # For each letter from 'a' to 't'
    for x in range(ord('a'), ord('t') + 1):
        # Convert to character
        x_char = chr(x)

        # Find all positions that need to be transformed from x
        positions = []
        for i in range(n):
            if A[i] == x_char and A[i] != B[i]:
                positions.append(i)

        if not positions:
            continue

        # Find the target letter for these positions
        target = B[positions[0]]

        # Count how many positions need this transformation
        count = 0
        for i in positions:
            if B[i] == target:
                count += 1

        # One move to transform from x to target
        moves += 1

    print(moves)
