        if divisors[0] != 2:
            print(-1)
            continue

        # Find product of all divisors
        product = 1
        for d in divisors:
            product *= d

        # Check if product is a perfect power
        # We expect product = x^(n/2)
        # Try to find x
        found = False
        for i in range(2, 1000000):
            # Check if i^(n/2) is close to product
            power = 1
            for j in range(n // 2):
                power *= i
            if power == product:
                x = i
                found = True
                break
            elif power > product:
                break

        if not found:
            print(-1)
            continue

        # Check if all divisors divide x
        valid = True
        for d in divisors:
            if x % d != 0:
                valid = False
                break

        if not valid:
