import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    vertices = set()

    idx = 1
    for _ in range(n):
        x = int(data[idx])
        y = int(data[idx + 1])
        vertices.add((x, y))
        idx += 2

    # Check if polygon is centrally symmetric
    if n % 2 != 0:
        print("NO")
        return

    for (x, y) in vertices:
        if (-x, -y) not in vertices:
            print("NO")
            return

    print("YES")

if __name__ == "__main__":
    solve()
"}

