# Compute prefix sums s where s[i] = a1 + a2 + ... + ai
s = [0] * (k + 1)
for i in range(1, k + 1):
    s[i] = s[i-1] + a[i-1]

# Try each b value as the one that could come from each position
# For each candidate x, check if all b values appear in the set
result = set()

for i in range(k + 1):
    for b_val in b:
        x = b_val - s[i]
        # Check if all b values appear in the set {x, x+s1, x+s2, ..., x+sk}
        valid = True
        for b2 in b:
            if b2 not in {x + s[j] for j in range(k + 1)}:
                valid = False
                break
        if valid:
            result.add(x)

print(len(result))
